[tool_call Write] {"file_path":"src/ratefile.rs","content":"//! Hand-written parser for the `.rates` tariff sheet format: `[section]`
//! headers, `key = value` entries, typed values (int / $money / percent% /
//! "string" / bool), `#` comments, and parse errors carrying 1-based line
//! numbers. No external crates — this parser is part of the deliverable.

use std::fmt;

use crate::money::Money;

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Str(String),
    Int(i64),
    Money(Money),
    Percent(u32),
    Bool(bool),
}

#[derive(Debug, Clone)]
pub struct ParseError {
    pub line: usize,
    pub message: String,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "rates:{}: {}", self.line, self.message)
    }
}

impl std::error::Error for ParseError {}

#[derive(Debug, Clone)]
struct Section {
    name: String,
    entries: Vec<(String, Value)>,
}

#[derive(Debug, Clone)]
pub struct RateFile {
    sections: Vec<Section>,
}

impl RateFile {
    pub fn parse(src: &str) -> Result<RateFile, ParseError> {
        let mut sections: Vec<Section> = Vec::new();
        for (idx, raw) in src.lines().enumerate() {
            let lineno = idx + 1;
            let fail = |message: &str| ParseError {
                line: lineno,
                message: message.to_string(),
            };

            let line = raw.trim_start();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }

            if line.starts_with('[') {
                let name =
                    parse_section_header(line).ok_or_else(|| fail("malformed section header"))?;
                if sections.iter().any(|s| s.name == name) {
                    return Err(fail(&format!("duplicate section '{}'", name)));
                }
                sections.push(Section {
                    name,
                    entries: Vec::new(),
                });
                continue;
            }

            if sections.is_empty() {
                return Err(fail("key before any section"));
            }

            // The key is everything before the first '=' (a '#' before any
            // '=' means the line has no '=' outside a comment).
            let eq = line
                .char_indices()
                .take_while(|(_, c)| *c != '#')
                .find(|(_, c)| *c == '=')
                .map(|(i, _)| i);
            let eq = match eq {
                Some(i) => i,
                None => return Err(fail("expected '=' after key")),
            };
            let key = line[..eq].trim();
            if key.is_empty() || !key.chars().all(is_key_char) {
                return Err(fail("malformed key"));
            }

            let value = parse_value(&line[eq + 1..]).map_err(|m| fail(m))?;

            let section = sections.last_mut().expect("checked non-empty above");
            if section.entries.iter().any(|(k, _)| k == key) {
                return Err(fail(&format!(
                    "duplicate key '{}' in section '{}'",
                    key, section.name
                )));
            }
            section.entries.push((key.to_string(), value));
        }
        Ok(RateFile { sections })
    }

    /// Section names in document order.
    pub fn sections(&self) -> Vec<&str> {
        self.sections.iter().map(|s| s.name.as_str()).collect()
    }

    /// Keys of a section in document order; empty for an unknown section.
    pub fn keys(&self, section: &str) -> Vec<&str> {
        match self.sections.iter().find(|s| s.name == section) {
            Some(s) => s.entries.iter().map(|(k, _)| k.as_str()).collect(),
            None => Vec::new(),
        }
    }

    pub fn get(&self, section: &str, key: &str) -> Option<&Value> {
        self.sections
            .iter()
            .find(|s| s.name == section)?
            .entries
            .iter()
            .find(|(k, _)| k == key)
            .map(|(_, v)| v)
    }
}

fn is_key_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_' || c == '-'
}

/// `[` name `]`, whitespace allowed just inside the brackets; only
/// whitespace or a comment may follow the `]`. None on any malformation.
fn parse_section_header(line: &str) -> Option<String> {
    let rest = line[1..].trim_start();
    let end = rest
        .char_indices()
        .find(|(_, c)| !(c.is_ascii_alphanumeric() || *c == '_'))
        .map(|(i, _)| i)
        .unwrap_or(rest.len());
    if end == 0 {
        return None;
    }
    let name = &rest[..end];
    let rest = rest[end..].trim_start().strip_prefix(']')?;
    let rest = rest.trim_start();
    if rest.is_empty() || rest.starts_with('#') {
        Some(name.to_string())
    } else {
        None
    }
}

/// Parse the text after '='. Returns the typed value or the exact error
/// message string.
fn parse_value(text: &str) -> Result<Value, &'static str> {
    let v = text.trim_start();

    if let Some(body) = v.strip_prefix('"') {
        // No escape sequences; the next '"' closes, and a '#' inside is data.
        let close = body.find('"').ok_or("unterminated string")?;
        check_trailing(&body[close + 1..])?;
        return Ok(Value::Str(body[..close].to_string()));
    }

    // First whitespace-delimited token; '#' starts a comment outside quotes.
    let end = v
        .char_indices()
        .find(|(_, c)| c.is_whitespace() || *c == '#')
        .map(|(i, _)| i)
        .unwrap_or(v.len());
    let token = &v[..end];
    if token.is_empty() {
        return Err("unrecognized value");
    }
    check_trailing(&v[end..])?;

    if let Some(amount) = token.strip_prefix('$') {
        return parse_money(amount).map(Value::Money).ok_or("bad money amount");
    }
    if let Some(body) = token.strip_suffix('%') {
        return parse_percent(body).map(Value::Percent).ok_or("bad percent");
    }
    match token {
        "true" => return Ok(Value::Bool(true)),
        "false" => return Ok(Value::Bool(false)),
        _ => {}
    }
    let digits = token.strip_prefix('-').unwrap_or(token);
    if !digits.is_empty() && digits.bytes().all(|b| b.is_ascii_digit()) {
        return token
            .parse::<i64>()
            .map(Value::Int)
            .map_err(|_| "unrecognized value");
    }
    Err("unrecognized value")
}

/// After a complete value only whitespace or a comment may follow.
fn check_trailing(rest: &str) -> Result<(), &'static str> {
    let rest = rest.trim_start();
    if rest.is_empty() || rest.starts_with('#') {
        Ok(())
    } else {
        Err("trailing characters after value")
    }
}

/// Digits, '.', then exactly two decimal digits (the leading '$' is already
/// stripped). None on any other shape.
fn parse_money(s: &str) -> Option<Money> {
    let (dollars, cents) = s.split_once('.')?;
    if dollars.is_empty()
        || !dollars.bytes().all(|b| b.is_ascii_digit())
        || cents.len() != 2
        || !cents.bytes().all(|b| b.is_ascii_digit())
    {
        return None;
    }
    let dollars: i64 = dollars.parse().ok()?;
    let cents: i64 = cents.parse().ok()?;
    Some(Money::from_cents(dollars.checked_mul(100)?.checked_add(cents)?))
}

/// [0-9]+ with an optional 1-2 digit decimal part (the trailing '%' is
/// already stripped), as basis points. None on any other shape.
fn parse_percent(s: &str) -> Option<u32> {
    let (whole, frac) = match s.split_once('.') {
        Some((w, f)) => (w, f),
        None => (s, ""),
    };
    if whole.is_empty() || !whole.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    let frac_bp = match frac.len() {
        0 => 0,
        1 if frac.bytes().all(|b| b.is_ascii_digit()) => frac.parse::<u32>().ok()? * 10,
        2 if frac.bytes().all(|b| b.is_ascii_digit()) => frac.parse::<u32>().ok()?,
        _ => return None,
    };
    whole
        .parse::<u32>()
        .ok()?
        .checked_mul(100)?
        .checked_add(frac_bp)
}
"}

[tool_call Write] {"file_path":"src/zones.rs","content":"//! Station-to-zone map and the directional lane table (origin zone, dest
//! zone) -> rate scale name.

use std::collections::BTreeMap;

/// Three-letter station code -> zone 1..9.
#[derive(Debug, Clone, Default)]
pub struct Zones {
    stations: BTreeMap<String, u8>,
}

impl Zones {
    pub fn new() -> Zones {
        Zones::default()
    }

    pub fn insert(&mut self, station: String, zone: u8) {
        self.stations.insert(station, zone);
    }

    pub fn zone_of(&self, station: &str) -> Option<u8> {
        self.stations.get(station).copied()
    }
}

/// (origin zone, dest zone) -> rate scale name. Directional: a 1-2 lane
/// does not imply 2-1.
#[derive(Debug, Clone, Default)]
pub struct Lanes {
    lanes: BTreeMap<(u8, u8), String>,
}

impl Lanes {
    pub fn new() -> Lanes {
        Lanes::default()
    }

    pub fn insert(&mut self, origin_zone: u8, dest_zone: u8, scale: String) {
        self.lanes.insert((origin_zone, dest_zone), scale);
    }

    pub fn scale_for(&self, origin_zone: u8, dest_zone: u8) -> Option<&str> {
        self.lanes
            .get(&(origin_zone, dest_zone))
            .map(|s| s.as_str())
    }
}
"}
[tool_call Write] {"file_path":"src/brackets.rs","content":"//! Weight-break rate scales: billed hundredweight, bracket selection
//! (floors inclusive), deficit-weight rebilling, and the scale minimum.

use crate::money::Money;

/// One weight break: the rate per cwt at and above `floor_lbs`.
#[derive(Debug, Clone, Copy)]
pub struct Bracket {
    pub floor_lbs: u32,
    pub rate: Money,
}

/// A rate scale: brackets sorted ascending by floor (a `from_0` bracket is
/// always present) plus the scale minimum charge.
#[derive(Debug, Clone)]
pub struct Scale {
    pub minimum: Money,
    pub brackets: Vec<Bracket>,
}

/// Rebilled at a higher bracket floor under the deficit-weight rule.
#[derive(Debug, Clone)]
pub struct Rebill {
    pub lbs: u32,
    pub cwt: u32,
    pub rate: Money,
    pub cost: Money,
}

/// The full linehaul story: natural billing, any deficit-weight rebill,
/// whether the scale minimum kicked in, and the resulting total.
#[derive(Debug, Clone)]
pub struct Linehaul {
    pub weight_lbs: u32,
    pub cwt: u32,
    pub rate: Money,
    pub base: Money,
    pub rebill: Option<Rebill>,
    pub minimum_applied: bool,
    pub total: Money,
}

impl Scale {
    pub fn price(&self, weight_lbs: u32) -> Linehaul {
        // Billed hundredweight: round up to the next full 100 lb.
        let cwt = (weight_lbs + 99) / 100;

        // Bracket floors are inclusive: the largest floor <= weight applies.
        let natural = self
            .brackets
            .iter()
            .rev()
            .find(|b| b.floor_lbs <= weight_lbs)
            .expect("schema guarantees a from_0 bracket");
        let base = cost_of(cwt, natural.rate);

        // Deficit-weight: price the shipment as if it weighed each higher
        // bracket's floor; rebill only if strictly cheaper. Scanning
        // ascending with a strict '<' keeps the natural bracket on a tie
        // and prefers the lower floor when two alternatives tie.
        let mut rebill: Option<Rebill> = None;
        for b in self.brackets.iter().filter(|b| b.floor_lbs > weight_lbs) {
            let alt_cwt = b.floor_lbs / 100;
            let cost = cost_of(alt_cwt, b.rate);
            let best = rebill.as_ref().map(|r| r.cost).unwrap_or(base);
            if cost < best {
                rebill = Some(Rebill {
                    lbs: b.floor_lbs,
                    cwt: alt_cwt,
                    rate: b.rate,
                    cost,
                });
            }
        }

        // The scale minimum applies after the deficit check.
        let mut total = rebill.as_ref().map(|r| r.cost).unwrap_or(base);
        let minimum_applied = total < self.minimum;
        if minimum_applied {
            total = self.minimum;
        }

        Linehaul {
            weight_lbs,
            cwt,
            rate: natural.rate,
            base,
            rebill,
            minimum_applied,
            total,
        }
    }
}

fn cost_of(cwt: u32, rate: Money) -> Money {
    Money::from_cents(cwt as i64 * rate.cents())
}
"}
[tool_call Write] {"file_path":"src/surcharge.rs","content":"//! Surcharge definitions and ordered application to a running total:
//! percent-vs-flat kinds, caps, `requires` flags, and contract waivers.

use std::collections::BTreeSet;

use crate::money::Money;

#[derive(Debug, Clone)]
pub enum Kind {
    /// Basis points of the running total at application time.
    Percent(u32),
    Flat(Money),
}

/// One surcharge as published on the sheet; application order is the order
/// the surcharge sections appear.
#[derive(Debug, Clone)]
pub struct SurchargeDef {
    pub code: String,
    pub label: String,
    pub kind: Kind,
    pub cap: Option<Money>,
    pub requires: Option<String>,
}

/// One surcharge as applied to a quote.
#[derive(Debug, Clone)]
pub struct Applied {
    pub code: String,
    pub percent: Option<u32>,
    pub base: Option<Money>,
    pub amount: Money,
    pub cap: Option<Money>,
    pub capped: bool,
    pub waived: bool,
}

/// Walk the sheet's surcharges in order against a running total. Surcharges
/// whose `requires` flag is absent are skipped silently; waived ones are
/// recorded at $0.00 so the audit trail shows them.
pub fn apply(
    defs: &[SurchargeDef],
    start: Money,
    flags: &BTreeSet<String>,
    waivers: &BTreeSet<String>,
) -> (Vec<Applied>, Money) {
    let mut running = start;
    let mut applied = Vec::new();
    for def in defs {
        if let Some(req) = &def.requires {
            if !flags.contains(req) {
                continue;
            }
        }
        if waivers.contains(&def.code) {
            applied.push(Applied {
                code: def.code.clone(),
                percent: match def.kind {
                    Kind::Percent(bp) => Some(bp),
                    Kind::Flat(_) => None,
                },
                base: None,
                amount: Money::from_cents(0),
                cap: def.cap,
                capped: false,
                waived: true,
            });
            continue;
        }
        let (percent, base, mut amount) = match def.kind {
            Kind::Percent(bp) => (Some(bp), Some(running), running.percent_of(bp)),
            Kind::Flat(m) => (None, None, m),
        };
        let mut capped = false;
        if let Some(cap) = def.cap {
            if amount > cap {
                amount = cap;
                capped = true;
            }
        }
        running = Money::from_cents(running.cents() + amount.cents());
        applied.push(Applied {
            code: def.code.clone(),
            percent,
            base,
            amount,
            cap: def.cap,
            capped,
            waived: false,
        });
    }
    (applied, running)
}
"}

