[tool_call Write] {"file_path":"src/tariff.rs","content":"//! Schema layer: interprets a parsed rate sheet into a `Tariff` (zones,
//! lanes, rate scales, ordered surcharges), rejecting structural problems
//! with exact schema error messages. Also owns loading from a file path.

use std::collections::BTreeMap;
use std::fmt;
use std::path::Path;

use crate::brackets::{Bracket, Scale};
use crate::money::Money;
use crate::ratefile::{ParseError, RateFile, Value};
use crate::surcharge::{Kind, SurchargeDef};
use crate::zones::{Lanes, Zones};

#[derive(Debug, Clone)]
pub struct Tariff {
    pub name: String,
    pub zones: Zones,
    pub lanes: Lanes,
    pub scales: BTreeMap<String, Scale>,
    pub surcharges: Vec<SurchargeDef>,
}

#[derive(Debug)]
pub enum TariffError {
    Parse(ParseError),
    Schema(String),
    Io(String),
}

impl fmt::Display for TariffError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TariffError::Parse(e) => write!(f, "{}", e),
            TariffError::Schema(m) => write!(f, "schema: {}", m),
            TariffError::Io(m) => write!(f, "io: {}", m),
        }
    }
}

impl std::error::Error for TariffError {}

impl Tariff {
    pub fn load(path: impl AsRef<Path>) -> Result<Tariff, TariffError> {
        let src = std::fs::read_to_string(path).map_err(|e| TariffError::Io(e.to_string()))?;
        Tariff::parse(&src)
    }

    pub fn parse(src: &str) -> Result<Tariff, TariffError> {
        let file = RateFile::parse(src).map_err(TariffError::Parse)?;
        validate(&file).map_err(TariffError::Schema)
    }
}

/// A key problem: "[{section}] {key}: {problem}".
fn key_err(section: &str, key: &str, problem: &str) -> String {
    format!("[{}] {}: {}", section, key, problem)
}

/// A section problem: "[{section}]: {problem}".
fn sec_err(section: &str, problem: &str) -> String {
    format!("[{}]: {}", section, problem)
}

fn validate(file: &RateFile) -> Result<Tariff, String> {
    let sections = file.sections();

    // Required sections first, in fixed order.
    for required in ["meta", "zones", "lanes"] {
        if !sections.contains(&required) {
            return Err(format!("missing section [{}]", required));
        }
    }

    let mut name = None;
    let mut zones = Zones::new();
    let mut lanes = Lanes::new();
    let mut scales = BTreeMap::new();
    let mut surcharges = Vec::new();

    // Walk sections, and keys within each, in document order; the first
    // problem wins.
    for section in &sections {
        match *section {
            "meta" => name = Some(validate_meta(file)?),
            "zones" => validate_zones(file, &mut zones)?,
            "lanes" => validate_lanes(file, &sections, &mut lanes)?,
            _ => {
                if let Some(scale_name) = section.strip_prefix("scale_") {
                    let scale = validate_scale(file, section, scale_name)?;
                    scales.insert(scale_name.to_string(), scale);
                } else if let Some(code) = section.strip_prefix("surcharge_") {
                    surcharges.push(validate_surcharge(file, section, code)?);
                } else {
                    return Err(sec_err(section, "unknown section"));
                }
            }
        }
    }

    Ok(Tariff {
        name: name.expect("meta section checked above"),
        zones,
        lanes,
        scales,
        surcharges,
    })
}

fn validate_meta(file: &RateFile) -> Result<String, String> {
    let mut name = None;
    for key in file.keys("meta") {
        match key {
            "name" => match file.get("meta", key) {
                Some(Value::Str(s)) => name = Some(s.clone()),
                _ => return Err(key_err("meta", key, "expected string")),
            },
            _ => return Err(key_err("meta", key, "unknown key")),
        }
    }
    name.ok_or_else(|| sec_err("meta", "missing key 'name'"))
}

fn validate_zones(file: &RateFile, zones: &mut Zones) -> Result<(), String> {
    for key in file.keys("zones") {
        if key.chars().count() != 3 || !key.chars().all(|c| c.is_ascii_uppercase()) {
            return Err(key_err("zones", key, "bad station code"));
        }
        match file.get("zones", key) {
            Some(Value::Int(z)) if (1..=9).contains(z) => {
                zones.insert(key.to_string(), *z as u8);
            }
            Some(Value::Int(_)) => return Err(key_err("zones", key, "zone must be 1..9")),
            _ => return Err(key_err("zones", key, "expected int")),
        }
    }
    Ok(())
}

fn validate_lanes(file: &RateFile, sections: &[&str], lanes: &mut Lanes) -> Result<(), String> {
    for key in file.keys("lanes") {
        let lane = match parse_lane_key(key) {
            Some(lane) => lane,
            None => return Err(key_err("lanes", key, "bad lane")),
        };
        let scale = match file.get("lanes", key) {
            Some(Value::Str(s)) => s,
            _ => return Err(key_err("lanes", key, "expected string")),
        };
        let scale_section = format!("scale_{}", scale);
        if !sections.iter().any(|s| *s == scale_section) {
            return Err(key_err("lanes", key, &format!("unknown scale '{}'", scale)));
        }
        lanes.insert(lane.0, lane.1, scale.clone());
    }
    Ok(())
}

/// `O-D` with O and D single digits 1-9.
fn parse_lane_key(key: &str) -> Option<(u8, u8)> {
    let b = key.as_bytes();
    if b.len() == 3 && (b'1'..=b'9').contains(&b[0]) && b[1] == b'-' && (b'1'..=b'9').contains(&b[2])
    {
        Some((b[0] - b'0', b[2] - b'0'))
    } else {
        None
    }
}

fn validate_scale(file: &RateFile, section: &str, scale_name: &str) -> Result<Scale, String> {
    if scale_name.is_empty()
        || !scale_name
            .chars()
            .all(|c| c.is_ascii_uppercase() || c.is_ascii_digit())
    {
        return Err(sec_err(section, "bad scale name"));
    }

    let mut minimum = None;
    let mut brackets: Vec<Bracket> = Vec::new();
    for key in file.keys(section) {
        if key == "minimum" {
            match file.get(section, key) {
                Some(Value::Money(m)) => minimum = Some(*m),
                _ => return Err(key_err(section, key, "expected money")),
            }
        } else if let Some(floor) = key.strip_prefix("from_") {
            if floor.is_empty() || !floor.bytes().all(|b| b.is_ascii_digit()) {
                return Err(key_err(section, key, "bad bracket key"));
            }
            let floor: u32 = floor
                .parse()
                .map_err(|_| key_err(section, key, "bad bracket key"))?;
            if floor % 100 != 0 {
                return Err(key_err(section, key, "floor must be a multiple of 100"));
            }
            match file.get(section, key) {
                Some(Value::Money(rate)) => brackets.push(Bracket {
                    floor_lbs: floor,
                    rate: *rate,
                }),
                _ => return Err(key_err(section, key, "expected money")),
            }
        } else {
            return Err(key_err(section, key, "unknown key"));
        }
    }

    let minimum = minimum.ok_or_else(|| sec_err(section, "missing key 'minimum'"))?;
    if !brackets.iter().any(|b| b.floor_lbs == 0) {
        return Err(sec_err(section, "missing key 'from_0'"));
    }
    brackets.sort_by_key(|b| b.floor_lbs);
    Ok(Scale { minimum, brackets })
}

fn validate_surcharge(file: &RateFile, section: &str, code: &str) -> Result<SurchargeDef, String> {
    if code.is_empty()
        || !code
            .chars()
            .all(|c| c.is_ascii_uppercase() || c.is_ascii_digit())
    {
        return Err(sec_err(section, "bad surcharge code"));
    }

    // `amount`'s expected type depends on `kind`, wherever it appears in
    // the section; an invalid or missing kind is reported on its own.
    let kind_str = match file.get(section, "kind") {
        Some(Value::Str(s)) => Some(s.as_str()),
        _ => None,
    };

    let mut label = None;
    let mut amount = None;
    let mut cap = None;
    let mut requires = None;
    for key in file.keys(section) {
        match key {
            "label" => match file.get(section, key) {
                Some(Value::Str(s)) => label = Some(s.clone()),
                _ => return Err(key_err(section, key, "expected string")),
            },
            "kind" => match file.get(section, key) {
                Some(Value::Str(s)) if s == "percent" || s == "flat" => {}
                Some(Value::Str(_)) => {
                    return Err(key_err(section, key, "must be 'percent' or 'flat'"))
                }
                _ => return Err(key_err(section, key, "expected string")),
            },
            "amount" => match kind_str {
                Some("percent") => match file.get(section, key) {
                    Some(Value::Percent(bp)) => amount = Some(Kind::Percent(*bp)),
                    _ => return Err(key_err(section, key, "expected percent")),
                },
                Some("flat") => match file.get(section, key) {
                    Some(Value::Money(m)) => amount = Some(Kind::Flat(*m)),
                    _ => return Err(key_err(section, key, "expected money")),
                },
                _ => {} // the kind problem is reported at the kind key
            },
            "cap" => match file.get(section, key) {
                Some(Value::Money(m)) => cap = Some(*m),
                _ => return Err(key_err(section, key, "expected money")),
            },
            "requires" => match file.get(section, key) {
                Some(Value::Str(s)) => requires = Some(s.clone()),
                _ => return Err(key_err(section, key, "expected string")),
            },
            _ => return Err(key_err(section, key, "unknown key")),
        }
    }

    let label = label.ok_or_else(|| sec_err(section, "missing key 'label'"))?;
    if kind_str.is_none() && file.get(section, "kind").is_none() {
        return Err(sec_err(section, "missing key 'kind'"));
    }
    let kind = amount.ok_or_else(|| sec_err(section, "missing key 'amount'"))?;

    Ok(SurchargeDef {
        code: code.to_string(),
        label,
        kind,
        cap,
        requires,
    })
}
"}

