[tool_call Write] {"file_path":"src/quote.rs","content":"//! The quote pipeline: resolve zones and lane, price the linehaul on the
//! lane's scale, stack surcharges in sheet order, produce a `Quote`.

use std::collections::BTreeSet;
use std::fmt;

use crate::brackets::Linehaul;
use crate::money::Money;
use crate::surcharge::{self, Applied};
use crate::tariff::Tariff;

#[derive(Debug, Clone)]
pub struct Shipment {
    pub reference: String,
    pub origin: String,
    pub dest: String,
    pub weight_lbs: u32,
    pub flags: BTreeSet<String>,
    pub waivers: BTreeSet<String>,
}

#[derive(Debug, PartialEq, Eq)]
pub enum QuoteError {
    BadWeight,
    UnknownStation(String),
    NoLane(u8, u8),
}

impl fmt::Display for QuoteError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            QuoteError::BadWeight => write!(f, "weight must be at least 1 lb"),
            QuoteError::UnknownStation(code) => write!(f, "unknown station '{}'", code),
            QuoteError::NoLane(o, d) => write!(f, "no lane from zone {} to zone {}", o, d),
        }
    }
}

impl std::error::Error for QuoteError {}

#[derive(Debug, Clone)]
pub struct Quote {
    pub reference: String,
    pub origin: String,
    pub dest: String,
    pub weight_lbs: u32,
    pub origin_zone: u8,
    pub dest_zone: u8,
    pub scale: String,
    pub linehaul: Linehaul,
    pub surcharges: Vec<Applied>,
    pub total: Money,
}

pub fn quote(tariff: &Tariff, shipment: &Shipment) -> Result<Quote, QuoteError> {
    if shipment.weight_lbs == 0 {
        return Err(QuoteError::BadWeight);
    }
    let origin_zone = tariff
        .zones
        .zone_of(&shipment.origin)
        .ok_or_else(|| QuoteError::UnknownStation(shipment.origin.clone()))?;
    let dest_zone = tariff
        .zones
        .zone_of(&shipment.dest)
        .ok_or_else(|| QuoteError::UnknownStation(shipment.dest.clone()))?;
    let scale_name = tariff
        .lanes
        .scale_for(origin_zone, dest_zone)
        .ok_or(QuoteError::NoLane(origin_zone, dest_zone))?;

    let scale = &tariff.scales[scale_name];
    let linehaul = scale.price(shipment.weight_lbs);
    let (surcharges, total) = surcharge::apply(
        &tariff.surcharges,
        linehaul.total,
        &shipment.flags,
        &shipment.waivers,
    );

    Ok(Quote {
        reference: shipment.reference.clone(),
        origin: shipment.origin.clone(),
        dest: shipment.dest.clone(),
        weight_lbs: shipment.weight_lbs,
        origin_zone,
        dest_zone,
        scale: scale_name.to_string(),
        linehaul,
        surcharges,
        total,
    })
}
"}
[tool_call Write] {"file_path":"src/audit.rs","content":"//! Audit-trail export: renders a `Quote` as the fixed plaintext format the
//! rating desk files with each quote — one line per applied rule, each with
//! the running total.

use std::fmt::Write;

use crate::money::Money;
use crate::quote::Quote;

pub fn render(quote: &Quote) -> String {
    let mut out = String::new();
    let _ = writeln!(
        out,
        "quote {} {} -> {} {} lb",
        quote.reference, quote.origin, quote.dest, quote.weight_lbs
    );
    let _ = writeln!(
        out,
        "lane: zone {} -> zone {}, scale {}",
        quote.origin_zone, quote.dest_zone, quote.scale
    );

    let lh = &quote.linehaul;
    let _ = writeln!(
        out,
        "linehaul: {} cwt @ {}/cwt = {} | total {}",
        lh.cwt, lh.rate, lh.base, lh.base
    );
    if let Some(r) = &lh.rebill {
        let _ = writeln!(
            out,
            "deficit-weight: rebill at {} lb, {} cwt @ {}/cwt = {} | total {}",
            r.lbs, r.cwt, r.rate, r.cost, r.cost
        );
    }
    if lh.minimum_applied {
        let _ = writeln!(
            out,
            "minimum-charge: raised to {} | total {}",
            lh.total, lh.total
        );
    }

    let mut running = lh.total;
    for s in &quote.surcharges {
        if s.waived {
            let _ = writeln!(
                out,
                "surcharge {}: waived by contract | total {}",
                s.code, running
            );
            continue;
        }
        running = Money::from_cents(running.cents() + s.amount.cents());
        let basis = match (s.percent, s.base) {
            (Some(bp), Some(base)) => format!("{}% of {}", percent(bp), base),
            _ => "flat".to_string(),
        };
        let capped = match (s.capped, s.cap) {
            (true, Some(cap)) => format!(", capped at {}", cap),
            _ => String::new(),
        };
        let _ = writeln!(
            out,
            "surcharge {} ({}{}): +{} | total {}",
            s.code, basis, capped, s.amount, running
        );
    }

    let _ = writeln!(out, "total: {}", quote.total);
    out
}

/// Basis points as the shortest exact decimal: 1250 -> "12.5", 400 -> "4",
/// 25 -> "0.25".
fn percent(bp: u32) -> String {
    let whole = bp / 100;
    let frac = bp % 100;
    if frac == 0 {
        format!("{}", whole)
    } else if frac % 10 == 0 {
        format!("{}.{}", whole, frac / 10)
    } else {
        format!("{}.{:02}", whole, frac)
    }
}
"}

